let store = MemoryStore::default();                  // or SqliteStore / RedisStore
let layer = SessionManagerLayer::new(store)
    .with_secure(true)
    .with_expiry(Expiry::OnInactivity(Duration::minutes(30)));
let app = Router::new().route("/me", get(me)).layer(layer);

async fn me(session: Session) -> impl IntoResponse {
    session.get::<String>("user").await.ok().flatten().unwrap_or_default()
}
